import random
import pandas as pd
import numpy as np

def task_func(n,
          domain="samplewebsite.com",
          categories=['Sports', 'Technology', 'Health', 'Science', 'Business'],
          random_seed=None):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if categories is None or len(categories) == 0:
        raise ValueError("categories must be a non-empty sequence")

    rng = random.Random(random_seed)
    np_rng = np.random.RandomState(random_seed)

    clean_domain = str(domain).rstrip("/")
    titles = [f"Article {i}" for i in range(n)]

    return pd.DataFrame({
        "title": titles,
        "title_url": [f"{clean_domain}/Article_{i}" for i in range(n)],
        "id": list(range(n)),
        "category": [rng.choice(categories) for _ in range(n)],
        "views": np_rng.poisson(lam=1000, size=n)
    })
